1	// Command mevwatch is the MEV 与链上风险监控系统 entry point.
2	package main
3	
4	import (
5		"encoding/json"
6		"fmt"
7		"io"
8		"os"
9		"strings"
10	
11		"github.com/gzhysuiioo/mevwatch-guard/mevwatch"
12	)
13	
14	func main() {
15		command := "demo"
16		if len(os.Args) > 1 {
17			command = os.Args[1]
18		}
19		switch command {
20		case "demo":
21			runDemo()
22		case "version":
23			fmt.Println("mevwatch 0.1.0")
24		case "replay":
25			runReplay(os.Args[2:])
26		case "report":
27			if len(os.Args) != 5 {
28				fmt.Fprintln(os.Stderr, "usage: mevwatch report <archive-dir> <chainId> <blockHash>")
29				os.Exit(2)
30			}
31			report, err := mevwatch.Query(os.Args[2], os.Args[3], os.Args[4])
