		{"fractional gas", `{"chainId":"1","blockHash":"0x","blockNumber":1,"swaps":[{"TxHash":"0x1","Pool":"p","Trader":"t","In":0,"Out":0,"GasPrice":1.5,"Index":0}]}`, 1},
