434	}
435	
436	func TestLegacyArchiveUsesBuiltinVersion(t *testing.T) {
437		dir := t.TempDir()
438		// Hand-write an archive in the pre-version format: no versions, no
439		// enabledVersion, records without a version field.
440		legacy := `{"records":[{"chainId":"1","blockHash":"0xleg","blockNumber":5,` +
441			`"swaps":[{"TxHash":"0xfront","Pool":"p1","Trader":"bot","In":500,"Out":480,"GasPrice":90,"Index":0},` +
442			`{"TxHash":"0xvictim","Pool":"p1","Trader":"user","In":200,"Out":188,"GasPrice":10,"Index":1},` +
443			`{"TxHash":"0xback","Pool":"p1","Trader":"bot","In":480,"Out":505,"GasPrice":80,"Index":2}],` +
444			`"findings":[{"kind":"sandwich","severity":3,"txHash":"0xvictim","evidence":[` +
445			`{"TxHash":"0xfront","Pool":"p1","Trader":"bot","In":500,"Out":480,"GasPrice":90,"Index":0},` +
446			`{"TxHash":"0xvictim","Pool":"p1","Trader":"user","In":200,"Out":188,"GasPrice":10,"Index":1},` +
447			`{"TxHash":"0xback","Pool":"p1","Trader":"bot","In":480,"Out":505,"GasPrice":80,"Index":2}]}]}]}`
448		if err := os.WriteFile(filepath.Join(dir, archiveFileName), []byte(legacy), 0o644); err != nil {
449			t.Fatal(err)
