		if err != nil {
			fmt.Fprintf(os.Stderr, "rules enable: %v\n", err)
			os.Exit(1)
		}
		writeJSON(version)
	default:
		fmt.Fprintf(os.Stderr, "unknown rules subcommand %q\n", args[0])
		usage()
		os.Exit(2)
	}
}

