	}
	suppression(t, dir,
		`{"id":"s1","chainId":"1","pool":"p1","kind":"sandwich","channel":"ch","start":0,"end":100,"reason":"r"}`)
	// History is unchanged; nothing new is processed.
	if again := generate(t, dir, "1", 0, 100, 3, "ch"); len(again) != 0 {
