func TestQueryAlertsMatchesGenerationOrder(t *testing.T) {
	dir := t.TempDir()
	replayBlocks(t, dir, twoFindingsBlock("0xb", 2), twoFindingsBlock("0xa", 1))
	gen := generate(t, dir, "1", 0, 100, 3, "ch")
